-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only published short placeholders, preserving existing text, and add each activity origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الإتقان وشرف العمل","passage":"استلم متدرب جهازًا يحتاج صيانة، ففحص القطع وسجل الملاحظات وطلب من مشرفه مراجعة إصلاحه قبل التسليم. يتضح في الموقف أن قيمة العمل تُقاس بالأمانة والإتقان، لا بالمسمى الوظيفي أو المظهر. هذا المثال مستقل من ضاديوم ولا يمثل نص القراءة المدرسي.","prompt":"ما السلوك الذي يدل على الإتقان؟","correct":"توثيق الفحص وطلب المراجعة","w1":"تجاهل الفحص","w2":"إخفاء العطل","w3":"التسليم بلا اختبار","practice":"اكتب موقفًا مهنيًا من ثماني جمل يوضح أثر الأمانة في جودة العمل مع سبب ونتيجة."},{"n":2,"skill":"القصر بالنفي والاستثناء","passage":"في «ما ارتفع مستوى الفريق إلا بالتدريب» اجتمع النفي «ما» وأداة الاستثناء «إلا» لتأكيد المعنى وقصر الارتفاع على التدريب في السياق المحدد. أما «لا يرتفع المستوى» فهي عبارة نفي وحدها، فلا يصح عدها قصرًا بالنفي والاستثناء.","prompt":"ما أداة الاستثناء في المثال؟","correct":"إلا","w1":"ما","w2":"الفريق","w3":"التدريب","practice":"أنشئ ثلاث جمل تدل على القصر بالنفي والاستثناء، ثم وضح ما قصرتَه على ماذا."},{"n":3,"skill":"تعليمات السلامة في الورشة","passage":"قبل فحص الأداة الكهربائية، افصل التغذية ثم تأكد من غياب التلف الظاهر، واستعن بالمشرف عند ظهور خلل. لا تستخدم جهازًا معطلًا ولا تستبدل دليل السلامة المعتمد بهذه البطاقة التدريبية. يعتمد وضوح التعليمات على ترتيب الأفعال وإيجاز الصياغة.","prompt":"ما أول إجراء في البطاقة؟","correct":"فصل مصدر التغذية","w1":"تشغيل الجهاز","w2":"تجاهل المشرف","w3":"إخفاء التلف","practice":"صمم قائمة سلامة من سبع تعليمات مرتبة، تتضمن صيغة أمر وصيغة نهي وإجراء تحقق."},{"n":4,"skill":"الطبع والتطبع وتعديل السلوك","passage":"يستلزم تحليل نص «الطبع والتطبع» لابن عبد ربه قراءة المصدر الأصلي للتحقق من موقف الكاتب. في حكاية من تأليف ضاديوم كان متدرب يتعجل الإجابة قبل سماع زملائه، ثم جرّب الإنصات وتدوين الأسئلة فصار النقاش أكثر فائدة. لا تنسب أحداث الحكاية إلى الكاتب.","prompt":"ما السلوك الجديد الذي مارسه المتدرب؟","correct":"الإنصات وتدوين الأسئلة","w1":"المقاطعة","w2":"تجاهل الآخرين","w3":"ترك النقاش","practice":"استخرج شاهدًا أصليًا موثقًا من نص «الطبع والتطبع» ثم قارنه بمثال من إنشائك عن اكتساب عادة."},{"n":5,"skill":"تخطيط الرحلة التعليمية","passage":"هيأ فريق زيارته الأولى إلى مركز مهني؛ حدد هدفًا للزيارة وأسئلة للمشرف وسجلًا لتوثيق ما يشاهده. أثناء الجولة ميّز الفريق بين الملاحظات المباشرة والمعلومات التي تتطلب مصدرًا. هذا النص الأصلي من ضاديوم لا ينقل أحداث القراءة المعنونة «على أبواب الرحلة الأولى».","prompt":"لماذا أعد الفريق قائمة أسئلة؟","correct":"لتنظيم جمع المعلومات","w1":"لإلغاء هدف الزيارة","w2":"لعدم الإصغاء","w3":"لاستبدال الملاحظات","practice":"اكتب يوميات زيارة تعليمية تصف الاستعداد وموقفًا واجهته ونتيجة تعلمتها دون معلومات غير موثقة."},{"n":6,"skill":"جزم المضارع بلا الناهية","passage":"في «لا تُهمِلْ معداتِ السلامة» تفيد «لا» طلب الكف عن الإهمال وتجزم الفعل المضارع «تهملْ» بالسكون. وفي «لا يُهملُ المسؤولُ السلامةَ» تفيد «لا» النفي، ويبقى المضارع مرفوعًا إذا لم يدخل عليه ناصب أو جازم آخر.","prompt":"كيف يُعرب الفعل «تهملْ» بعد لا الناهية؟","correct":"مضارع مجزوم بالسكون","w1":"مضارع مرفوع بالضمة","w2":"ماض مبني","w3":"أمر مبني","practice":"كوّن أربع جمل عن الورشة بلا الناهية، ثم اضبط المضارع في كل جملة وعلل."},{"n":7,"skill":"الحجاج بالسرد وأثر الأنانية","passage":"لا يمكن نسبة حكاية إلى «الفردية سوس ينخر المجتمع» لخليل هنداوي دون نص موثق. في قصة أصلية خبأ عضو فريق نتائج قياساته رغبة في الانفراد بالإنجاز، فتأخرت المهمة. عندما شارك البيانات تمكن زملاؤه من إكمال العمل؛ يحمل تسلسل الأحداث حجة ضد الأنانية.","prompt":"ما نتيجة احتفاظ العضو بالبيانات؟","correct":"تأخر إنجاز المهمة","w1":"تحسن التعاون فورًا","w2":"انتهت المهمة مبكرًا","w3":"زادت دقة التقرير تلقائيًا","practice":"بعد قراءة النص المدرسي استخرج حجة حقيقية وشاهدًا، ثم اكتب قصة قصيرة توظف سردًا لإقناع القارئ."},{"n":8,"skill":"بنية الرسالة والنصيحة","passage":"ورد في رسالة تدريبية من ضاديوم: «يا بنيّ، يسعدني سعيك إلى فهم ما يصعب عليك. اسأل حين تحتاج إلى مساعدة، ولا تجعل الخطأ آخر محاولاتك». تظهر صيغة النداء والمخاطبة المباشرة والنصيحة العملية، ولا يمثل ذلك رسالة «إلى ابني» المقررة.","prompt":"ما النصيحة التي حملتها الرسالة؟","correct":"السؤال والتعلم من الخطأ","w1":"عدم المحاولة مجددًا","w2":"إخفاء الصعوبة","w3":"ترك الدراسة","practice":"اكتب رسالة من عشرة أسطر إلى قريب أصغر سنًا تجمع تحية ونصيحتين معللتين وخاتمة."},{"n":9,"skill":"النعت والمطابقة","passage":"في «اشتريتُ جهازًا جديدًا» نعت «جديدًا» منصوب مثل منعوته النكرة «جهازًا». وفي «الأدواتُ الجديدةُ منظّمةٌ» يتبع النعت المنعوت في التعريف والإعراب، وقد يوصف جمع غير العاقل بمفرد مؤنث. لا تخلط النعت بخبر الجملة.","prompt":"ما وظيفة «جديدًا» في «اشتريت جهازًا جديدًا»؟","correct":"نعت منصوب","w1":"مبتدأ مرفوع","w2":"مفعول به ثان","w3":"فاعل","practice":"اكتب أربع جمل عن أدوات مهنية، وأعرب المنعوت والنعت مع مراعاة التذكير والتأنيث والتعريف."},{"n":10,"skill":"تلخيص الفكرة دون نسخ","passage":"في نص أصلي: «راجع الفريق القياسات أكثر من مرة، فعثر على خطأ في الأطوال وعدّل المخطط قبل التصنيع». يحافظ الملخص الصحيح على العلاقة بين الفحص والنتيجة مثل «ساعد تكرار القياس على اكتشاف خطأ المخطط قبل التنفيذ». أما تكرار الألفاظ دون فهم فلا يكفي.","prompt":"ما خلاصة العلاقة بين التحقق والنتيجة؟","correct":"كشف التحقق خطأ المخطط مبكرًا","w1":"لم يفحص الفريق العمل","w2":"صُنع المنتج بلا مخطط","w3":"لم يظهر أي خطأ","practice":"اختر نصًا قصيرًا مسموحًا باستخدامه، ولخصه في خمس جمل مع مراجعة الفكرة والأسباب والنتائج."},{"n":901,"skill":"أركان التشبيه وأنواعه","passage":"«الفنيُّ كالنحلةِ في نشاطه» تشبيه مرسل مفصل؛ الفني مشبه والنحلة مشبه به والكاف أداة التشبيه والنشاط وجه الشبه. في «الفنيُّ نحلةٌ» تحذف الأداة ووجه الشبه فيصبح تشبيهًا بليغًا في السياق. لا نفهم التعبير على أنه حقيقة علمية.","prompt":"ما وجه الشبه في المثال الأول؟","correct":"النشاط","w1":"الفني","w2":"النحلة","w3":"الكاف","practice":"أنشئ ثلاثة تشبيهات أصلية حول مواقف مدرسية أو مهنية، واستخرج الأركان والغرض من كل تشبيه."},{"n":902,"skill":"الكنز المادي والمعنوي","passage":"في نص قصصي مستقل فتحت طالبة خزانة المدرسة القديمة ظنًا أنها تضم مقتنيات باهظة، فإذا فيها مذكرات لطلاب سابقين تسجل إخفاقاتهم وكيف تجاوزوها. وجدت في الخبرة المتراكمة كنزًا معرفيًا. لا يُنسب هذا المثال إلى نص «الكنوز الضائعة» دون الرجوع إليه.","prompt":"ما الذي جعل المذكرات ذات قيمة للطالبـة؟","correct":"احتواؤها تجارب ودروسًا عملية","w1":"وجود ذهب فيها","w2":"حداثة أوراقها فقط","w3":"كون الخزانة مغلقة","practice":"بعد قراءة النص المقرر قارن مفهوم الكنز فيه بمفهوم من كتابتك مع شاهد موثق من المصدر."},{"n":903,"skill":"التوكيد وهمزتا الوصل والقطع","passage":"«إنَّ الدقةَ نافعةٌ» فيها توكيد بـ«إنَّ» واسمها منصوب، وهمزة «إنَّ» همزة قطع. أما «اكتبْ ملاحظاتِك» فتبدأ بهمزة وصل في أمر الفعل الثلاثي، تُنطق ابتداءً وتسقط في الوصل لفظًا. يختلف رسم الهمزة بحسب أصل الكلمة وقاعدتها.","prompt":"أي كلمة تبدأ بهمزة وصل في المثالين؟","correct":"اكتب","w1":"إنَّ","w2":"الدقة","w3":"نافعة","practice":"صنّف عشر كلمات إلى همزة وصل وقطع، ثم أنشئ جملة توكيد وحدد اسم إن وخبرها."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='e15ed6fd-370c-4980-b724-d0c19ec2c029'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 804 — اللغة العربية للتعليم الفني والمهني' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G11_T2_ARAB804_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_TECH_G11_T2_ARAB804_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G11_T2_ARAB804_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_TECH_G11_T2_ARAB804_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;